      ctx.fillRect(-len / 2 + 5, wid / 2 - 2.6, ww, wh);
      ctx.fillRect(len / 2 - 12, -wid / 2 - 2, ww, wh);
      ctx.fillRect(len / 2 - 12, wid / 2 - 2.6, ww, wh);
      if (v.def.taxi) {
