        const phase = Math.floor(v.sirenPhase) % 2;
        ctx.fillStyle = phase ? '#ff3b30' : '#2e7dff';
        ctx.beginPath();
        ctx.arc(-4, 0, 4.4, 0, Math.PI * 2);
