    drawPerson(ped.x, ped.y, ped.angle, ped.shirt, ped.skin, ped.walkCycle, false);
  }
  for (const h of G.hostiles) {
    if (h.health <= 0 || !inView(view, h.x, h.y, 30)) continue;
