  }
  for (const o of G.officers) {
    if (!inView(view, o.x, o.y, 30)) continue;
    drawPerson(o.x, o.y, o.angle, '#22355e', o.skin || '#e0ac69', o.walkCycle, G.wanted.stars >= 4);
  }
