  ctx.beginPath();
  ctx.moveTo(obj.x - 9, obj.y - 120);
  ctx.lineTo(obj.x + 9, obj.y - 120);
  ctx.lineTo(obj.x, obj.y);
  ctx.closePath();
  ctx.fill();
